function previousSnapshotMember(playerId, role, power, donation, bossAttacks, lastActivityDays, source, seenAt = null) {
  return {
    playerId,
    role,
    power,
    contribution7d: donation,
    bossAttacks,
    lastActivityDays,
    lastSeenAt: seenAt,
    verificationNote: `Previous screenshot check: ${source}.`,
  };
}

function rawSnapshotMember(playerId, role, power, donation, bossAttacks, lastActivityDays, source, seenAt = null, name = null) {
  return {
    playerId,
    name,
    role,
    power,
    contribution7d: donation,
    bossAttacks,
    bossDamageToday: null,
    lastActivityDays,
    lastSeenAt: seenAt,
    verificationNote: `Screenshot check: ${source}.`,
  };
}

function rawBossSnapshotRow(source, rowIndex, seenAt = null, data = {}) {
  return {
    source,
    rowIndex,
    area: data.area ?? "list",
    bossRank: data.bossRank ?? null,
    playerId: data.playerId ?? null,
    name: data.name ?? null,
    rawName: data.rawName ?? null,
    damageText: data.damageText ?? null,
    bossDamageToday: data.bossDamageToday ?? null,
    rowLabel: data.area === "podium" ? `Top ${data.bossRank ?? rowIndex + 1}` : `Boss row ${rowIndex + 1}`,
    lastSeenAt: seenAt,
  };
}

