function screenshotMember(playerId, role, power, donation, bossAttacks, lastActivityDays, source, seenAt = null) {
  const previous = previousSnapshotFor(playerId);
  return {
    playerId,
    role,
    status: "active",
    joinedAt: captures.baselineJoinedAt,
    power,
    power7d: null,
    power14dPercent: null,
    contributionToday: null,
    contribution7d: donation,
    contributionTotal: null,
    bossDamageToday: null,
    bossDamageTotal: null,
    bossRank: null,
    bossAttacks,
    bossAttacksDelta: numberDelta(bossAttacks, previous?.bossAttacks),
    lastActivityDays,
    contributionDelta: weeklyDonationDelta(donation, previous?.contribution7d, seenAt, previous?.lastSeenAt),
    powerDelta: numberDelta(power, previous?.power),
    previousSnapshot: previous,
    lastSeenAt: seenAt ?? previous?.lastSeenAt ?? null,
    metricsVerified: true,
    verificationNote: `Screenshot check: ${source}.`,
  };
}

function previousSnapshotFor(playerId) {
  return previousMemberSnapshots.find((snapshot) => snapshot.playerId === playerId) ?? null;
}

function numberDelta(current, previous) {
  return typeof current === "number" && typeof previous === "number" ? current - previous : null;
}

function weeklyDonationDelta(current, previous, currentDate, previousDate) {
  if (typeof current !== "number" || typeof previous !== "number") return null;
  if (currentDate && previousDate && weekStartDate(currentDate) !== weekStartDate(previousDate) && current < previous) return null;
  return current - previous;
}

function weekStartDate(value) {
  const [year, month, day] = String(value).split("-").map(Number);
  if (!year || !month || !day) return "";
  const current = new Date(Date.UTC(year, month - 1, day, 12));
  const weekday = current.getUTCDay() || 7;
  current.setUTCDate(current.getUTCDate() - weekday + 1);
  return current.toISOString().slice(0, 10);
}

